import json
from pathlib import Path
updates=[]
def u(pages,title,note,url): updates.append(dict(pages=pages,title=title,note=note,url=url))
u([26,27],'External ID is not a secret','External ID identifies the vendor’s customer in a trust-policy condition. Bukan password; vendor should generate a unique value for each customer to prevent the confused deputy problem.','https://docs.aws.amazon.com/IAM/latest/UserGuide/id_roles_common-scenarios_third-party.html')
u([59],'ForAllValues does not require every allowed tag','It validates all supplied values against the allowed set. It can be true when the key is absent. Untuk mewajibkan tag, add existence checks and explicit required RequestTag conditions.','https://docs.aws.amazon.com/IAM/latest/UserGuide/reference_policies_condition-single-vs-multi-valued-context-keys.html')
u([117,118],'ACM public certificates can be exportable','Exportable public certificates can be deployed to EC2 and outside AWS; fees apply. Kamu must distribute renewed exported certificates to those endpoints. The old blanket “cannot export public ACM certificates” is incomplete.','https://docs.aws.amazon.com/acm/latest/userguide/acm-exportable-certificates.html')
u([129,340],'S3 has native EventBridge events','Enable EventBridge delivery on the S3 bucket and route events with rules. CloudTrail data events are a different path, bukan mandatory prerequisite for native S3 events.','https://docs.aws.amazon.com/AmazonS3/latest/userguide/EventBridge.html')
u([140],'S3 Object Lambda has customer eligibility restrictions','Since 7 November 2025, availability is limited to existing customers and selected APN partners. Pahami pattern transform-on-read, but do not assume a new customer can adopt this service.','https://docs.aws.amazon.com/AmazonS3/latest/userguide/transforming-objects.html')
u([226,227,231],'Lambda CPU and payload numbers need correction','1,769 MB provides one vCPU equivalent, not two. Standard invocation duration remains up to 15 minutes. Current asynchronous invocation payload limit is 1 MB; synchronous request/response limits differ. Bedakan quota, adjustable concurrency, and application requirements.','https://docs.aws.amazon.com/lambda/latest/dg/gettingstarted-limits.html')
u([238],'ALB supports mutual TLS','ALB supports certificate verification and passthrough modes. Jadi “only Classic Load Balancer supports two-way TLS” is outdated. Match certificate handling and target needs to the mode.','https://docs.aws.amazon.com/elasticloadbalancing/latest/application/mutual-authentication.html')
u([248],'ALB cross-zone has target-group controls','Cross-zone is on at the ALB level. It can be disabled for eligible target groups, with feature restrictions. Jangan menghafal “impossible to disable anywhere.”','https://docs.aws.amazon.com/elasticloadbalancing/latest/application/edit-target-group-attributes.html')
u([253,259,790],'29 seconds is not universal for REST integrations','Regional and private REST API integration timeouts can be increased beyond 29 seconds; this may require a lower account throttle quota. Edge-optimized REST APIs retain the 29-second maximum. Tanyakan API type terlebih dahulu.','https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-execution-service-limits-table.html')
u([388,389],'Prefer CloudFront trusted key groups','Use trusted key groups for signed URLs/cookies. Your application signs using its private key; it does not call CloudFront to create each URL. Root-account key pairs are a legacy alternative, bukan required design.','https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/private-content-trusted-signers.html')
u([429,430,431,432],'RDS Multi-AZ depends on deployment type','A Multi-AZ DB instance has a standby that does not serve reads. A Multi-AZ DB cluster has two readable standby instances. Bedakan this from a read replica and from Aurora architecture.','https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/Concepts.MultiAZ.html')
u([452],'Express workflow delivery semantics have two modes','Standard workflows use exactly-once workflow execution. Asynchronous Express uses at-least-once; synchronous Express uses at-most-once. External side effects still need careful retry and idempotency design.','https://docs.aws.amazon.com/step-functions/latest/dg/choosing-workflow-type.html')
u(list(range(626,631)),'Snowball is restricted for new customers','Since 7 November 2025, Snowball Edge is available only to existing customers. For a new project, evaluate current transfer options such as DataSync, Data Transfer Terminal, or partners. Slide device specifications are historical study context.','https://aws.amazon.com/snowball/faqs/')
u([658,659],'VPC addressing is more flexible than RFC 1918','Private RFC 1918 IPv4 ranges are recommended, not the only allowed ranges. Using a public range internally does not automatically make it internet-routable. Selalu check overlap and routing.','https://docs.aws.amazon.com/vpc/latest/userguide/vpc-cidr-blocks.html')
u([660,661,662],'AWS offers private IPv6 addressing','AWS supports private IPv6 through IPAM as well as public IPv6. Private IPv6 is not advertised to the internet. Public IPv6 reachability still depends on routes and security rules; alamat global tidak otomatis terbuka.','https://docs.aws.amazon.com/vpc/latest/userguide/vpc-ip-addressing.html')
u([788,789,790],'An API Gateway 502 is not a unique concurrency diagnosis','With Lambda integration, function errors or malformed responses can produce 502. A rejected Lambda invocation produces 500 in the documented integration behavior. Lihat logs and metrics before choosing a fix.','https://docs.aws.amazon.com/lambda/latest/dg/services-apigateway-errors.html')
tables=[]
def t(title,headers,rows,note,pages): tables.append(dict(title=title,headers=headers,rows=rows,note=note,pages=pages))
t('Permission layers',['Layer','What it does','Bahasa decision cue'],[
['Identity policy','Grants actions to users/roles','Apa identity boleh lakukan?'],['Resource policy / trust policy','Names principals that may access / assume','Siapa boleh masuk?'],['Permissions boundary','Maximum identity permissions','Batas delegasi; tidak memberi izin sendiri'],['SCP','Maximum permissions in organization accounts','Pagar organisasi; tidak memberi izin sendiri'],['Session policy','Narrows an STS session','Batas untuk sesi sementara'],['Explicit deny','Overrides an applicable allow','Deny yang berlaku menang']], 'The simple intersection mental model has resource-policy and principal-type exceptions. Use the IAM lessons for full context.',[9,58])
t('Encryption choices',['Choice','Who manages keys?','Use when / pilih ketika'],[['SSE-S3','S3-managed keys','Simple at-rest encryption'],['SSE-KMS','KMS key and key policy','Audit, control, separation of duties; account for KMS permissions'],['SSE-C','Caller supplies key per request','You accept key handling responsibility'],['Client-side encryption','Application encrypts before upload','Data must arrive at S3 already encrypted'],['CloudHSM','Customer controls dedicated HSMs','Special crypto/compliance requirements justify operational work']], 'TLS is in-transit protection. Encryption does not substitute for authorization.',[81,102])
t('Security service decoder',['Question','Service','Bahasa'],[['Who called which API?','CloudTrail','Audit aktivitas'],['What changed in configuration?','Config','Riwayat konfigurasi dan compliance rules'],['Is there suspicious activity?','GuardDuty','Deteksi ancaman'],['Which software vulnerabilities exist?','Inspector','Vulnerability assessment'],['Where is sensitive S3 data?','Macie','Temukan data sensitif'],['How do I aggregate findings?','Security Hub','Pusat findings'],['How do I investigate relationships?','Detective','Analisis investigasi'],['How do I block bad web requests?','WAF','Filter HTTP(S)'],['How do I protect against DDoS?','Shield','Mitigasi serangan volumetrik and related protections']], 'Detection, investigation, prevention and remediation are different jobs.',[142,173])
t('Storage decision',['Need','Start with','Why / alasan'],[['One instance disk','EBS','Block storage; AZ-scoped volume'],['Shared Linux files','EFS','NFS shared file system'],['Windows SMB + AD','FSx for Windows','Windows file semantics'],['HPC parallel files','FSx for Lustre','High-throughput parallel access'],['Objects, backups, static assets','S3','Object API; not a normal POSIX disk'],['Local high-speed disposable scratch','Instance store','Treat data as ephemeral'],['On-prem file access backed by S3','S3 File Gateway','Local cache with object-backed storage']], 'Choose semantics first; then availability, throughput, latency and cost.',[318,374])
t('S3 access pattern',['Class / family','Access pattern','Key trade-off'],[['Standard','Frequent access','No retrieval delay'],['Intelligent-Tiering','Uncertain or changing access','Monitoring and tier behavior; understand optional archive tiers'],['Standard-IA','Infrequent but fast retrieval','Retrieval fees and minimum-duration billing'],['One Zone-IA','Re-creatable infrequently accessed data','Single-AZ resilience trade-off'],['Glacier Instant Retrieval','Rare access with millisecond retrieval','Archive pricing with retrieval charges'],['Glacier Flexible Retrieval','Archive with restore waiting','Expedited / standard / bulk retrieval modes'],['Glacier Deep Archive','Long-term archive; hours acceptable','Lowest-cost intent with longer restore times']], 'Use the slides for worked pricing examples only. Current prices, minimum billable size, and exact restore options require the current service table.',[325,339])
t('Load balancer & edge',['Requirement','Candidate','Avoid this confusion'],[['HTTP host/path rules','ALB','Layer 7 routing ≠ raw TCP'],['TCP/UDP or static per-AZ addresses','NLB','Layer 4 does not inspect HTTP paths'],['Third-party virtual appliances','GWLB','GENEVE encapsulation and symmetric inspection path'],['Cache HTTP content globally','CloudFront','A CDN can reduce origin work'],['Static anycast IPs + global network routing','Global Accelerator','Does not cache your objects'],['DNS-based endpoint selection','Route 53','Client caching/TTL affect failover speed']], 'A solution can combine DNS, CDN and an origin load balancer.',[233,312])
t('Relational and NoSQL',['Need','Candidate','Decisive check'],[['Relational transactions','RDS / Aurora','Engine, availability, read/write patterns'],['Key-value predictable low latency','DynamoDB','Partition key and access patterns'],['Cache hot data','ElastiCache','Staleness, invalidation and failure behavior'],['Warehouse analytics','Redshift','Columnar analytical workload'],['SQL on S3','Athena','Scan volume, partitions and file format'],['Document compatibility','DocumentDB','Validate MongoDB compatibility, not identity'],['Time-series workload','Timestream family','Check current offering and eligibility'],['Graph relationships','Neptune (exam scope extension)','Traversal requirements, not relational joins by default']], 'A read replica primarily scales reads; traditional Multi-AZ standby primarily protects availability. Deployment type matters.',[408,444])
t('Messaging and streaming',['Service','Unit and behavior','Pick when'],[['SQS','Queue; consumer deletes after processing','Workers compete; buffer uneven load'],['SNS','Push pub/sub topic','Fan-out to independent subscribers'],['EventBridge','Event bus and content-based rules','Route application/service events'],['Kinesis Data Streams','Partitioned retained stream','Ordered shard data, replay, independent consumers'],['Amazon Data Firehose','Buffered delivery','Deliver to destinations with low operations work'],['Managed Service for Apache Flink','Stateful stream processing','Windows, event time, aggregations'],['Amazon MQ','Managed broker','Existing protocol/client compatibility'],['Step Functions','State machine','Retries, branches and orchestration']], 'At-least-once delivery requires idempotent processing. FIFO scope and deduplication do not make every external side effect exactly once.',[445,506])
t('Network troubleshooting',['Layer','Ask','Typical fix'],[['Addressing','Do CIDRs overlap? Does source have the needed address type?','Plan non-overlapping ranges / translation'],['DNS','Does the correct name resolve on this side?','Resolver rules, private zones, endpoint DNS'],['Routing','Is there a forward AND return route?','Route tables, propagation, IGW/NAT/TGW'],['Security group','Does the stateful rule allow the initiated flow?','Correct protocol/port/source/destination'],['Network ACL','Do stateless rules allow both directions?','Include return ephemeral ports'],['Application permissions','Does the API allow the principal?','Identity/resource/endpoint/KMS policies'],['Service health','Is the listener and target healthy?','Health checks and application logs']], 'A network path and an authorization path must both work. Direct Connect does not automatically encrypt every connection.',[657,723])
t('The 7 Rs',['R','Meaning','Bahasa example'],[['Retire','Remove the workload','Matikan aplikasi yang tidak diperlukan'],['Retain','Keep for now','Tunda karena constraint'],['Rehost','Move with limited app change','Lift-and-shift VM'],['Relocate','Move a platform with minimal redesign','Move supported virtualized environment'],['Repurchase','Replace with another product','Beralih ke SaaS'],['Replatform','Change platform with limited architecture change','Managed database migration'],['Refactor / re-architect','Redesign application','Break dependencies; redesign for cloud']], 'The right R comes from business constraints, dependencies, time and value—not from maximum modernization.',[611,617])
t('Migration tool decoder',['Need','Service','Operational question'],[['Discover dependencies and inventory','Application Discovery Service / Migration Hub','Which waves and dependencies?'],['Move server workloads','Application Migration Service (MGN)','Cutover testing and rollback?'],['Replicate relational data','DMS','Full load + CDC? Schema conversion needed?'],['Move online file/object data','DataSync','Bandwidth, validation and incremental transfer?'],['Hybrid file/block/tape interface','Storage Gateway','Which protocol and local cache?'],['Server disaster recovery','Elastic Disaster Recovery (DRS)','Recovery drills and failback?'],['Central backup policy','AWS Backup','Vault access, copies, retention and restores?']], 'Moving data is only part of migration. Include identity, DNS, application dependencies and validation.',[611,656])
t('Disaster recovery spectrum',['Strategy','What runs in recovery location','Trade-off'],[['Backup and restore','Backups; infrastructure reconstructed','Lower running cost, longer recovery'],['Pilot light','Critical data/core components','Provision/scale the rest during recovery'],['Warm standby','Complete application at reduced capacity','Scale up; higher cost, shorter recovery'],['Multi-site active/active','Application serves from multiple sites','Highest coordination complexity; data consistency matters']], 'RPO = tolerable data loss measured in time. RTO = tolerable restoration time. Test actual recovery; labels do not guarantee targets.',[643,656])
t('Deployment patterns',['Pattern','Traffic change','Risk and cost'],[['In-place','Replace on current capacity','Possible interruption; rollback depends on state'],['Rolling','Replace in batches','Mixed versions must coexist'],['Blue/green','Switch between environments','Fast traffic rollback; more capacity'],['Canary','Small share then larger share','Observe early before full rollout'],['Linear','Equal increments over time','Gradual exposure']], 'A traffic rollback does not undo incompatible database writes. Plan schema compatibility.',[549,582])
t('AI/ML jargon by input/output',['Need','Service','Bahasa'],[['Image/video labels','Rekognition','Memahami visual'],['OCR + forms/tables','Textract','Ekstrak dokumen terstruktur'],['Text sentiment/entities','Comprehend','Memahami bahasa'],['Speech → text','Transcribe','Transkripsi'],['Text → speech','Polly','Suara sintetis'],['Language → another language','Translate','Terjemahan'],['Conversational interface','Lex','Intent dan dialog'],['Custom model training/deployment','SageMaker','Workflow ML kustom'],['Enterprise knowledge search','Kendra','Pencarian informasi']], 'These are recognition cues, not guarantees of accuracy or substitutes for checking the exact supported input.',[724,741])
